import { Avatar, AvatarFallback, Button } from '@cognite/aura/components';
import { IconMapPin, IconPlus } from '@tabler/icons-react';
import { type ReactNode, useState } from 'react';

import { MapLayoutLeftPanel } from './map-layout-left-panel';
import { MapLayoutMapArea } from './map-layout-map-area';
import { MapLayoutPreview } from './map-layout-preview';
import { MapLayoutTable } from './map-layout-table';
import {
  mapPageDescription,
  mapPageTitle,
  mapPrimaryAction,
  mapSecondaryAction,
  mapSiteRows,
  type MapLayerListView,
  type MapLayout,
} from './map-layout-template.data';

function hasLeftPanel(layout: MapLayout): boolean {
  return layout === 'left-right-panels';
}

function hasRightPanel(layout: MapLayout): boolean {
  return layout !== 'grid-full-width';
}

function hasDataGrid(layout: MapLayout): boolean {
  return layout === 'grid-right-panel' || layout === 'grid-full-width';
}

function hasPageHeader(layout: MapLayout): boolean {
  return layout === 'grid-right-panel' || layout === 'grid-full-width';
}

function PageHeader(): ReactNode {
  return (
    <header
      data-slot="page-header"
      className="flex items-center gap-3 border-b px-3 py-3"
    >
      <div className="flex flex-1 items-center gap-3">
        <Avatar className="size-9 shrink-0">
          <AvatarFallback>
            <IconMapPin size={18} stroke={1.5} />
          </AvatarFallback>
        </Avatar>
        <div className="flex flex-col">
          <h1 className="text-base font-medium leading-5">{mapPageTitle}</h1>
          <p className="text-sm text-muted-foreground">{mapPageDescription}</p>
        </div>
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <Button variant="secondary">{mapSecondaryAction}</Button>
        <Button>
          <IconPlus size={16} stroke={1.5} />
          {mapPrimaryAction}
        </Button>
      </div>
    </header>
  );
}

function MapLayoutTemplate({
  layout,
  layers = 'tree',
}: {
  layout: MapLayout;
  layers?: MapLayerListView;
}): ReactNode {
  const [selectedIds, setSelectedIds] = useState<ReadonlySet<string>>(
    () => new Set()
  );
  const [selectedSiteId, setSelectedSiteId] = useState<string | null>(() =>
    hasRightPanel(layout) ? (mapSiteRows[0]?.id ?? null) : null
  );

  const selectedSite = mapSiteRows.find((s) => s.id === selectedSiteId);

  function toggleRow(id: string): void {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  function toggleAll(): void {
    setSelectedIds((prev) => {
      if (mapSiteRows.every((row) => prev.has(row.id))) {
        return new Set();
      }
      return new Set(mapSiteRows.map((row) => row.id));
    });
  }

  return (
    <div
      data-slot="map-layout-template"
      className="flex h-[52rem] w-full min-w-0 flex-col overflow-hidden rounded-xl border bg-background"
    >
      {hasPageHeader(layout) && <PageHeader />}

      <div className="flex min-h-0 flex-1">
        {hasLeftPanel(layout) && <MapLayoutLeftPanel list={layers} />}

        <div className="flex min-w-0 flex-1 flex-col">
          <MapLayoutMapArea
            selectedSiteId={selectedSiteId}
            onSelectSite={setSelectedSiteId}
            className={hasDataGrid(layout) ? 'min-h-[45%]' : undefined}
          />

          {hasDataGrid(layout) && (
            <MapLayoutTable
              selectedIds={selectedIds}
              onToggleRow={toggleRow}
              onToggleAll={toggleAll}
              selectedRowId={selectedSiteId}
              onSelectRow={setSelectedSiteId}
            />
          )}
        </div>

        {hasRightPanel(layout) && selectedSite && (
          <MapLayoutPreview site={selectedSite} />
        )}
      </div>
    </div>
  );
}

MapLayoutTemplate.displayName = 'MapLayoutTemplate';

export { MapLayoutTemplate };

import {
  Button,
  Item,
  ItemCheckbox,
  ItemGroup,
  ItemSectionHeader,
  ItemSectionHeaderTitle,
  ItemTitle,
  Search,
  Tree,
} from '@cognite/aura/components';
import { IconFilter } from '@tabler/icons-react';
import { type ReactNode, useState } from 'react';

import {
  mapLayerDefaultChecked,
  mapLayerDefaultExpanded,
  mapLayerNodes,
  mapLayerRootId,
  type MapLayerListView,
  type MapLayerNode,
} from './map-layout-template.data';

function LayerTree(): ReactNode {
  return (
    <Tree<MapLayerNode>
      rootItemId={mapLayerRootId}
      items={mapLayerNodes}
      getChildren={(item) => [...item.children]}
      getItemName={(item) => item.name}
      defaultExpandedItems={mapLayerDefaultExpanded}
      checkboxes
      defaultCheckedItems={mapLayerDefaultChecked}
    >
      {(item) => <ItemTitle>{item.getItemName()}</ItemTitle>}
    </Tree>
  );
}

function LayerItems({
  ids,
  depth,
  checkedIds,
  onToggle,
}: {
  ids: readonly string[];
  depth: number;
  checkedIds: ReadonlySet<string>;
  onToggle: (id: string) => void;
}): ReactNode {
  return ids.map((id) => {
    const node = mapLayerNodes[id];
    if (!node) {
      return null;
    }
    return (
      <LayerItemRows
        key={id}
        id={id}
        node={node}
        depth={depth}
        checkedIds={checkedIds}
        onToggle={onToggle}
      />
    );
  });
}

function LayerItemRows({
  id,
  node,
  depth,
  checkedIds,
  onToggle,
}: {
  id: string;
  node: MapLayerNode;
  depth: number;
  checkedIds: ReadonlySet<string>;
  onToggle: (id: string) => void;
}): ReactNode {
  return (
    <>
      <Item>
        {Array.from({ length: depth }, (_, index) => (
          <span
            key={`${id}-indent-${index}`}
            aria-hidden="true"
            className="w-4 shrink-0"
          />
        ))}
        <ItemCheckbox
          aria-label={`Select ${node.name}`}
          checked={checkedIds.has(id)}
          onCheckedChange={() => onToggle(id)}
        />
        <ItemTitle>{node.name}</ItemTitle>
      </Item>
      {node.children.length > 0 && (
        <LayerItems
          ids={node.children}
          depth={depth + 1}
          checkedIds={checkedIds}
          onToggle={onToggle}
        />
      )}
    </>
  );
}

function LayerItemList(): ReactNode {
  const [checkedIds, setCheckedIds] = useState<ReadonlySet<string>>(
    () => new Set(mapLayerDefaultChecked)
  );
  const groups = mapLayerNodes[mapLayerRootId]?.children ?? [];

  function toggle(id: string): void {
    setCheckedIds((current) => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  return (
    <div className="flex flex-col gap-2">
      {groups.map((groupId) => {
        const group = mapLayerNodes[groupId];
        if (!group) {
          return null;
        }
        return (
          <section key={groupId}>
            <ItemSectionHeader>
              <ItemSectionHeaderTitle>{group.name}</ItemSectionHeaderTitle>
            </ItemSectionHeader>
            <ItemGroup>
              <LayerItems
                ids={group.children}
                depth={0}
                checkedIds={checkedIds}
                onToggle={toggle}
              />
            </ItemGroup>
          </section>
        );
      })}
    </div>
  );
}

function MapLayoutLeftPanel({
  list = 'tree',
}: {
  list?: MapLayerListView;
}): ReactNode {
  return (
    <aside
      data-slot="map-left-panel"
      aria-label="Layers"
      className="flex w-[282px] shrink-0 flex-col border-r"
    >
      <div className="flex items-center gap-2 px-3 py-3">
        <Search
          aria-label="Search layers"
          placeholder="Search layers"
          className="flex-1"
        />
        <Button variant="secondary" size="icon" aria-label="Filter">
          <IconFilter size={16} stroke={1.5} />
        </Button>
      </div>
      <div className="flex flex-1 flex-col overflow-y-auto px-1 pb-3">
        {list === 'item' ? <LayerItemList /> : <LayerTree />}
      </div>
    </aside>
  );
}

MapLayoutLeftPanel.displayName = 'MapLayoutLeftPanel';

export { MapLayoutLeftPanel };

import { cn } from '@cognite/aura/utils';
import type { ReactNode } from 'react';

import {
  Map,
  MapMarker,
  MapMarkerDot,
  MapMarkerLabel,
  naturalEarth10m,
  type MapPaletteName,
  type MapStatus,
} from '../map/map';

import {
  mapSiteRows,
  type MapAssetStatus,
  type MapSiteRow,
} from './map-layout-template.data';

const statusTones: Record<MapAssetStatus, MapStatus> = {
  Online: 'success',
  Warning: 'warning',
  Offline: 'critical',
  Maintenance: 'neutral',
};

const siteColors: MapPaletteName[] = [
  'fjord',
  'dusk',
  'aurora',
  'sky',
  'orange',
  'nordic',
  'mountain',
  'fjord',
  'dusk',
  'aurora',
];

function MapLayoutMapArea({
  className,
  selectedSiteId,
  onSelectSite,
}: {
  className?: string;
  selectedSiteId?: string | null;
  onSelectSite?: (siteId: string) => void;
}): ReactNode {
  return (
    <div
      data-slot="map-area"
      className={cn('relative min-h-0 min-w-0 flex-1', className)}
    >
      <Map
        center={[4.5, 56.6]}
        zoom={3.6}
        geography={naturalEarth10m}
        className="absolute inset-0"
      >
        {mapSiteRows.map((site, index) => (
          <SiteMarker
            key={site.id}
            site={site}
            color={siteColors[index % siteColors.length] ?? 'fjord'}
            selected={selectedSiteId === site.id}
            onSelect={() => onSelectSite?.(site.id)}
          />
        ))}
      </Map>
    </div>
  );
}

function SiteMarker({
  site,
  color,
  selected,
  onSelect,
}: {
  site: MapSiteRow;
  color: MapPaletteName;
  selected: boolean;
  onSelect: () => void;
}): ReactNode {
  return (
    <MapMarker
      longitude={site.longitude}
      latitude={site.latitude}
      anchor="bottom"
      className="flex cursor-pointer flex-col items-center gap-1"
      onClick={onSelect}
    >
      {selected ? (
        <MapMarkerLabel color={color} dot>
          {site.name}
        </MapMarkerLabel>
      ) : (
        <MapMarkerDot
          color={color}
          status={statusTones[site.status]}
          pulse={site.status === 'Online'}
          size="large"
          role="img"
          aria-label={`${site.name}: ${site.status}`}
        />
      )}
    </MapMarker>
  );
}

MapLayoutMapArea.displayName = 'MapLayoutMapArea';

